import { test, expect } from '@playwright/test';

test.describe('User Registration', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/register');
  });

  test('should show error message for already-used email', async ({ page }) => {
    await page.fill(getByLabel('Email'), 'existinguser@example.com');
    await page.fill(getByLabel('Password'), 'SecurePassword123');
    await page.fill(getByLabel('Confirm Password'), 'SecurePassword123');
    await page.click(getByRole('button', { name: 'Register' }));

    const errorMessage = await page.getByText('Email already in use. Please use a different email.');
    await expect(errorMessage).toBeVisible();
  });

  test('should not show error message for unique email', async ({ page }) => {
    await page.fill(getByLabel('Email'), 'newuser@example.com');
    await page.fill(getByLabel('Password'), 'SecurePassword123');
    await page.fill(getByLabel('Confirm Password'), 'SecurePassword123');
    await page.click(getByRole('button', { name: 'Register' }));

    const successMessage = await page.getByText('Registration successful!');
    await expect(successMessage).toBeVisible();
  });
});
